var ErrEmptyQueue = errors.New("queue is empty")

type Queue struct {
	items []int
}

func (q *Queue) Pop() (int, error) {
	if len(q.items) == 0 {
		return 0, ErrEmptyQueue
	}
	last := len(q.items) - 1
	v := q.items[last]
	q.items = q.items[:last]
	return v, nil
}

func main() {
	q := &Queue{}
	_, err := q.Pop()
	if err == ErrEmptyQueue {
		fmt.Println("nothing to pop -- that's an expected, handleable case")
	} else if err != nil {
		fmt.Println("unexpected error:", err)
	}

