package main

import (
	"errors"
	"fmt"
)

var ErrPermission = errors.New("permission denied")

func openFile() error {
	return ErrPermission
}

func loadSettings() error {
	if err := openFile(); err != nil {
		return fmt.Errorf("loading settings: %w", err)
	}
	return nil
}

func startApp() error {
	if err := loadSettings(); err != nil {
		return fmt.Errorf("starting app: %w", err)
	}
	return nil
}

func main() {
	err := startApp()
	fmt.Println(err)                              // starting app: loading settings: permission denied
	fmt.Println(errors.Is(err, ErrPermission))   // true
}

package main

import (
	"errors"
	"fmt"
)

var ErrTimeout = errors.New("request timed out")

func fetch() error {
	return ErrTimeout
}

func callAPI() error {
	if err := fetch(); err != nil {
		return fmt.Errorf("calling API: %v", err)   // %v, not %w -- looks identical when printed
	}
	return nil
}

func main() {
	err := callAPI()
	fmt.Println(err)                          // calling API: request timed out
	fmt.Println(errors.Is(err, ErrTimeout)) // false -- the chain was never actually formed
}

package main

import (
	"errors"
	"fmt"
)

type ValidationError struct {
	Field string
	Value string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("invalid value %q for field %q", e.Value, e.Field)
}

func validate(age string) error {
	return &ValidationError{Field: "age", Value: age}
}

func handleRequest(age string) error {
	if err := validate(age); err != nil {
		return fmt.Errorf("handling request: %w", err)
	}
	return nil
}

func main() {
	err := handleRequest("twelve")

	var ve *ValidationError
	if errors.As(err, &ve) {
		fmt.Printf("field %q rejected, got %q\n", ve.Field, ve.Value)
	}

