import "fmt"

func step3() {
	defer fmt.Println("step3 cleanup")
	panic("failure in step3")
}

func step2() {
	defer fmt.Println("step2 cleanup")
	step3()
}

func step1() {
	defer fmt.Println("step1 cleanup")
	step2()
}

func main() {
	step1()
}
// step3 cleanup
// step2 cleanup
// step1 cleanup
// panic: failure in step3
// ...

package main

import "fmt"

func safeDivide(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	result = a / b
	return
}

func main() {
	r, err := safeDivide(10, 0)
	fmt.Println(r, err)     // 0 recovered: runtime error: integer divide by zero

	r, err = safeDivide(10, 5)
	fmt.Println(r, err)     // 2 <nil>
}

package main

import (
	"fmt"
	"time"
)

func worker(id int) {
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("worker", id, "recovered from:", r)
		}
	}()
	if id == 2 {
		panic("bad input for worker 2")
	}
	fmt.Println("worker", id, "finished normally")
}

func main() {
	for i := 1; i <= 3; i++ {
		worker(i)
	}
	fmt.Println("main finished -- every worker's panic stayed contained")
}

